import{d as l,N as e,i as a,l as o}from"./chunks/framework.DAESqsOv.js";const f=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍","outline":"deep"},"headers":[],"relativePath":"rich-text/introduction.md","filePath":"rich-text/introduction.md","lastUpdated":1778847587000}'),t={name:"rich-text/introduction.md"};function r(c,i,d,h,n,s){return e(),a("div",null,[...i[0]||(i[0]=[o('<h1 id="富文本" tabindex="-1">富文本 <a class="header-anchor" href="#富文本" aria-label="Permalink to &quot;富文本&quot;">​</a></h1><p><code>@norio-office/rich-text</code> 是一个基于 <code>Vue 3 + Tiptap 3</code> 的富文本编辑器组件，内置文档式编辑界面、图片/视频/文件块、表格、公式、倒计时、高亮块、大纲、预览模式、导出能力，以及可选的 <code>Yjs</code> 协同编辑。</p><blockquote><p>当前组件仍处于持续迭代阶段。用于生产环境前，请结合业务场景做充分测试；发现问题可反馈至 <code>norio-office@qq.com</code>。</p></blockquote><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>在业务系统中嵌入一个文档式在线编辑器</li><li>需要图片、视频、附件、表格、公式、Markdown 导入等内容块</li><li>需要导出 PDF、图片、HTML 或直接打印内容</li><li>需要只读预览、移动端阅读缩放、大纲导航和演示模式</li><li>需要由业务侧完全控制上传、下载、鉴权和文件存储</li><li>需要可选接入多人协同编辑、远程光标和共享文档状态</li></ul><h2 id="产品特点" tabindex="-1">产品特点 <a class="header-anchor" href="#产品特点" aria-label="Permalink to &quot;产品特点&quot;">​</a></h2><ul><li>文档式体验：内置页面化编辑界面、大纲、预览、演示和全屏能力。</li><li>内容块丰富：支持图片、视频、文件、本地文件卡片、表格、分栏、公式、高亮块、倒计时、链接、Emoji、分隔线和 Markdown 导入。</li><li>导出能力完整：支持 PDF、图片、HTML 和打印，水印会保留到 PDF、图片和打印结果里。</li><li>业务边界清晰：上传 hook 只接收 <code>File</code> 并等待业务返回最终 URL，组件不会内置业务上传接口，也不会自动回退为 base64/blob URL。</li><li>接入方式可裁剪：通过白名单 props 控制导出项、插入菜单项和工具栏动作。</li><li>协同能力可选：单人模式和 <code>Yjs</code> 协同模式共用一套组件 API。</li></ul><h2 id="主要能力" tabindex="-1">主要能力 <a class="header-anchor" href="#主要能力" aria-label="Permalink to &quot;主要能力&quot;">​</a></h2><h3 id="文本编辑" tabindex="-1">文本编辑 <a class="header-anchor" href="#文本编辑" aria-label="Permalink to &quot;文本编辑&quot;">​</a></h3><ul><li>标题、正文、字体、字号</li><li>颜色、高亮、加粗、斜体、下划线、删除线</li><li>上标、下标、行内代码</li><li>无序列表、有序列表、任务列表</li><li>对齐、缩进、引用</li></ul><h3 id="内容插入" tabindex="-1">内容插入 <a class="header-anchor" href="#内容插入" aria-label="Permalink to &quot;内容插入&quot;">​</a></h3><ul><li>图片和视频</li><li>文件链接/预览块</li><li>本地文件卡片</li><li>链接、表格、分栏</li><li>公式、代码块、高亮块</li><li>日期、倒计时、Emoji、分隔线</li><li>Markdown 导入</li><li><code>@</code> 人员/文档提及</li></ul><h3 id="文档辅助" tabindex="-1">文档辅助 <a class="header-anchor" href="#文档辅助" aria-label="Permalink to &quot;文档辅助&quot;">​</a></h3><ul><li>左侧或右侧内置大纲</li><li>可外置的 <code>RichTextOutline</code> 目录组件</li><li>当前章节高亮和点击跳转</li><li>预览模式和移动端缩放</li><li>页面水印</li></ul><h3 id="输出能力" tabindex="-1">输出能力 <a class="header-anchor" href="#输出能力" aria-label="Permalink to &quot;输出能力&quot;">​</a></h3><ul><li>导出 PDF</li><li>导出图片，支持 PNG/JPEG</li><li>导出 HTML</li><li>内容区打印</li></ul><h3 id="协同能力" tabindex="-1">协同能力 <a class="header-anchor" href="#协同能力" aria-label="Permalink to &quot;协同能力&quot;">​</a></h3><ul><li>基于 <code>Yjs</code> 的共享文档编辑</li><li>可选接入 <code>y-websocket</code> 等 provider</li><li>支持远程光标和远程选区显示</li><li>随包附带最小 Yjs WebSocket 服务示例</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li>先看 <a href="/office-docs/rich-text/getting-started">快速开始</a></li><li>如果有多人协同需求，再看 <a href="/office-docs/rich-text/collaboration">协同编辑</a></li><li>再看 <a href="/office-docs/rich-text/api">API 文档</a></li><li>最后看 <a href="/office-docs/rich-text/demo">Demo 演示</a> 和 <a href="/office-docs/rich-text/playground">在线演示</a></li></ol>',20)])])}const b=l(t,[["render",r]]);export{f as __pageData,b as default};
